custom_css:
/* ================================================================
 * WPS文档 —— 上班摸鱼用：酒馆看起来就是一份在写的 WPS 文档
 *
 * 作者：mangosagocreamwithpomelo（Discord）
 * 设计与实现：Claude Opus 5.5（Anthropic）
 *
 * 标题栏、功能区、标尺、状态栏是照着 WPS Office 12（Windows，默认浅色皮肤，125% 缩放）
 * 一像素一像素量出来的；图标是重新画的线稿。最好按 F11 全屏，浏览器的地址栏就不见了。
 *
 * 顶上那排选项卡就是酒馆的各个面板：
 *   文件 = 角色　开始 = 预设（AI 响应配置）　插入 = 世界书　页面 = 背景　引用 = 用户人设
 *   审阅 = 高级格式　视图 = 用户设置　工具 = 扩展　WPS AI = API 连接
 * ================================================================ */

/* ================================================================
 * 可改区：想调整的都在这里，改完点空白处即可生效。改坏了重新导入主题就能恢复。
 * ================================================================ */
html:root {
    /* —— 假装在写的文档 —— */
    --wps-docname: '第三季度工作总结.docx';   /* 标题栏标签上的文件名 */
    --wps-title: '2026年第三季度工作总结';     /* 第一页顶上的大标题，'' 不要 */
    --wps-count: '2,817';                     /* 字数：电脑在状态栏「字数: 」后面，手机在左下角「全文: 」后面 */
    --wps-tip: '文档内按F1，可快速查找并解决办公问题';   /* 启动页底部的小贴士（电脑） */
    --wps-tip-m: '双指缩放，可以调整文档的显示大小';     /*                  （手机） */
    --wps-m-pad: 18px;              /* 手机：正文到屏幕左右两边的距离 */

    /* —— 正文 —— */
    --wps-body-font: SimSun, '宋体', 'Songti SC', 'Noto Serif SC', serif;   /* 想用仿宋：FangSong, '仿宋', STFangsong, serif */
    --wps-body-size: 14px;          /* 五号 = 14px；小四 = 16px */
    --wps-line: 1.5;                /* 行距：1.5 倍行距；WPS 的「单倍」约 1.3 */
    --wps-indent: 2em;              /* 首行缩进（装了主题伴侣：拖标尺上的小倒三角） */
    --wps-page-ml: 120px;           /* 电脑：左页边距（WPS 默认 3.18cm ≈ 120px；装了主题伴侣：拖标尺的灰白交界） */
    --wps-page-mr: 120px;           /*       右页边距 */
    --wps-name: inline;             /* 说话人「星野澪：」：inline 放段首 / none 不显示 */
    --wps-em-font: KaiTi, '楷体', STKaiti, 'Kaiti SC', serif;  /* 心理描写（*斜体*）用楷体；想跟正文一样改成 inherit */

    /* —— 颜色（文档里的字在「用户设置 → UI 主题」里改） —— */
    --wps-chrome-top: #EAEDF2;      /* 窗口底色：左上偏蓝灰 */
    --wps-chrome-bottom: #EEE5DE;   /*         右下偏暖 */
    --wps-paper: #FFFFFF;           /* 纸 */
    --wps-page-edge: #C2C2C2;       /* 纸边 */
    --wps-blue: #1E5FC7;            /* 选中的选项卡 */
    --wps-ui-ink: #222222;          /* 菜单文字 */
    --wps-ui-font: 'Microsoft YaHei UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', sans-serif;
}
/* ======================== 可改区结束 ======================== */

